form.script:
function syncCustomerUI() {
    var actExist = document.getElementById("crm_customer_action_exist");
    var compSec = document.getElementById("crm_convert_modal_company_section");
    var partSec = document.getElementById("crm_convert_modal_partner_section");
    var compSel = document.getElementById("crm_convert_modal_company_select");
    var partSel = document.getElementById("crm_convert_modal_partner_select");

    var isExist = !!(actExist && actExist.checked);
    if (isExist) {
        if (compSec) compSec.style.setProperty("display", "none", "important");
        if (partSec) partSec.style.setProperty("display", "flex", "important");
        if (compSel) compSel.disabled = true;
        if (partSel) partSel.disabled = false;
    } else {
        if (compSec) compSec.style.setProperty("display", "flex", "important");
        if (partSec) partSec.style.setProperty("display", "none", "important");
        if (compSel) compSel.disabled = false;
        if (partSel) partSel.disabled = true;
    }
}
window.syncCustomerUI = syncCustomerUI;

div.script:
document.addEventListener('DOMContentLoaded', function () {
    var input = document.getElementById('crm_lost_search_input');
    if (!input) return;
    input.addEventListener('input', function () {
        var q = input.value.toLowerCase().trim();
        var rows = document.querySelectorAll('.crm-lost-row');
        var vis = 0;
        rows.forEach(function (r) {
            var txt = r.getAttribute('data-search') || '';
            var match = (!q || txt.indexOf(q) !== -1);
            r.style.display = match ? '' : 'none';
            if (match) {
                vis++;
            }
        });
        var badge = document.getElementById('crm_lost_badge_count');
        if (badge) badge.textContent = vis;
        var count = document.getElementById('crm_lost_footer_count');
        if (count) {
            count.textContent = vis > 0 ? ('1-' + vis + ' of ' + vis) : '0 of 0';
        }
        var noRow = document.getElementById('crm_lost_no_records_row');
        if (noRow) {
            if (vis === 0 && rows.length > 0) {
                noRow.style.display = '';
            } else {
                noRow.style.display = 'none';
            }
        }
    });
});

document.addEventListener('DOMContentLoaded', function () {
    var input = document.getElementById('crm_lost_search_input');
    if (!input) return;
    var currSym = "";
    input.addEventListener('input', function () {
        var q = input.value.toLowerCase().trim();
        var rows = document.querySelectorAll('.crm-lost-row');
        var vis = 0;
        var totalRev = 0;
        rows.forEach(function (r) {
            var txt = r.getAttribute('data-search') || '';
            var match = (!q || txt.indexOf(q) !== -1);
            r.style.display = match ? '' : 'none';
            if (match) {
                vis++;
                var rev = parseFloat(r.getAttribute('data-revenue') || '0');
                if (!isNaN(rev)) {
                    totalRev += rev;
                }
            }
        });
        var badge = document.getElementById('crm_lost_badge_count');
        if (badge) badge.textContent = vis;
        var count = document.getElementById('crm_lost_footer_count');
        if (count) {
            count.textContent = vis > 0 ? ('1-' + vis + ' of ' + vis) : '0 of 0';
        }
        var totalEl = document.getElementById('crm_lost_footer_total');
        if (totalEl) {
            totalEl.textContent = 'Total lost ' + currSym + totalRev.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
        }
        var noRow = document.getElementById('crm_lost_no_records_row');
        if (noRow) {
            if (vis === 0 && rows.length > 0) {
                noRow.style.display = '';
            } else {
                noRow.style.display = 'none';
            }
        }
    });
});
